9	/// Cedar schema (human syntax). One `Principal` type (kind as an attribute); the tenancy
10	/// nodes form the resource hierarchy with a synthetic `Root` at the top.
11	pub const SCHEMA_SRC: &str = r#"
12	namespace Pgs::Iam {
13	  entity Root;
14	  entity Organization in [Root] { effective_status: String };
15	  entity Team in [Organization] { effective_status: String };
16	  entity Project in [Team] { effective_status: String };
17	  entity Principal { kind: String, status: String };
18	
19	  action GetOrganization, ListOrganizations, GetTeam, ListTeams, GetProject, ListProjects,
20	         ListMemberships, CreateOrganization, RenameOrganization, ArchiveOrganization,
21	         RestoreOrganization, CreateTeam, RenameTeam, ArchiveTeam, RestoreTeam, CreateProject,
22	         RenameProject, ArchiveProject, RestoreProject, AttachMembership, DetachMembership,
23	         PutPolicy, DeletePolicy, ListPolicies, GrantRole, RevokeRole, ListRoleGrants,
24	         CreateServiceAccount, GetServiceAccount, ListServiceAccounts, ArchiveServiceAccount,
25	         IssueApiKey, RevokeApiKey, ListApiKeys, ListAuditLog
26	    appliesTo { principal: [Principal], resource: [Root, Organization, Team, Project] };
27	}
28	"#;
29	
30	pub fn schema() -> &'static Schema {
31	    static SCHEMA: OnceLock<Schema> = OnceLock::new();
32	    SCHEMA.get_or_init(|| Schema::from_str(SCHEMA_SRC).expect("embedded Cedar schema is valid"))
33	}
