35	/// Validate a policy's syntax + schema conformance at write time.
36	pub fn validate_policy(src: &str) -> Result<(), AuthzError> {
37	    use cedar_policy::{PolicySet, ValidationMode, Validator};
38	    let pset = PolicySet::from_str(src).map_err(|e| AuthzError::PolicyParse(e.to_string()))?;
39	    let result = Validator::new(schema().clone()).validate(&pset, ValidationMode::default());
40	    if result.validation_passed() {
41	        Ok(())
42	    } else {
43	        Err(AuthzError::SchemaValidation(format!("{result:?}")))
44	    }
45	}
