55	    fn a_wellformed_permit_validates() {
56	        assert!(validate_policy(r#"permit(principal, action == Pgs::Iam::Action::"GetOrganization", resource);"#).is_ok());
57	    }
58	    #[test]
59	    fn a_malformed_policy_is_rejected() {
60	        assert!(validate_policy("permit(this is not cedar);").is_err());
