77	/// Generic-by-value over most of the ports it depends on, mirroring `AuthenticateToken`
78	/// (M1/M2 use-case DI pattern) — `cache` is the one exception: `Arc<dyn ApiKeyValidationCache>`,
79	/// the SAME shared handle `ServiceAccountService`/`ApiKeyService` hold (module docs above), so a
80	/// revoke/archive's `cache.evict` is visible to this use case's `cache.get` without a second
81	/// cache instance to keep in sync.
82	#[derive(Clone)]
83	pub struct AuthenticateApiKey<K, P, H, C, M> {
84	    keys: K,
85	    principals: P,
86	    hasher: H,
87	    clock: C,
88	    cache: Arc<dyn ApiKeyValidationCache>,
89	    memberships: M,
90	    config: ApiKeyConfig,
91	}
92	
93	impl<K, P, H, C, M> AuthenticateApiKey<K, P, H, C, M>
94	where
95	    K: ApiKeyRepository,
96	    P: PrincipalRepository,
97	    H: SecretHasher,
98	    C: Clock,
99	    M: MembershipRepository,
100	{
101	    #[allow(clippy::too_many_arguments)]
102	    pub fn new(keys: K, principals: P, hasher: H, clock: C, cache: Arc<dyn ApiKeyValidationCache>, memberships: M, config: ApiKeyConfig) -> Self {
103	        AuthenticateApiKey {
104	            keys,
105	            principals,
106	            hasher,
107	            clock,
108	            cache,
109	            memberships,
110	            config,
111	        }
112	    }
113	
114	    /// Validates `token` and resolves it to the service account's `AuthnPrincipal` (spec §9).
115	    /// `parse_token` failures (wrong prefix, oversized, malformed keyid/secret encoding) map
116	    /// straight to `InvalidToken` before any port is touched. Otherwise cache-first: a hit
117	    /// short-circuits to [`Self::resolve_cached`]; a miss falls through to [`Self::resolve_uncached`],
118	    /// the full DB validation.
119	    pub async fn resolve(&self, token: &str) -> Result<AuthnPrincipal, AuthnError> {
120	        let parsed = parse_token(&self.config.key_prefix, token, self.config.max_token_bytes).map_err(invalid_token)?;
121	
122	        match self.cache.get(parsed.key_id).await {
123	            Some(cached) => self.resolve_cached(parsed.key_id, &parsed.secret, cached).await,
124	            None => self.resolve_uncached(parsed).await,
125	        }
126	    }
127	
128	    /// The cache-HIT path (module docs). The `key_id` a hit is keyed by is a NON-secret token
129	    /// segment (`pgs_sk_<keyid>_<secret>`), so a hit MUST still prove possession of the secret —
130	    /// it saves the two DB round-trips (`find_by_id` + `find_principal`), NOT the secret check:
131	    ///
132	    /// 1. `hasher.verify(secret, cached.key_hash)` (constant-time, against the SAME peppered hash
133	    ///    stored in Postgres and cached in [`CachedValidation`]) — a mismatch is an ATTACK (a
134	    ///    wrong secret against a live cached key), not a revocation: deny `InvalidToken(BadSecret)`
135	    ///    and do NOT evict (evicting on a wrong-secret guess would let an attacker knock a valid
136	    ///    key out of the cache, forcing a DB round-trip — a mild DoS lever; a genuine revocation
137	    ///    evicts via `RevokeApiKey`/`ArchiveServiceAccount`, never from here).
138	    /// 2. `expires_at` — past `clock.now()` -> evict + `InvalidToken` (a stale positive entry the
139	    ///    caller is entitled to have age out).
140	    /// 3. the cached `sa_status` -> `PrincipalInactive` if not `Active`.
141	    ///
142	    /// Secret FIRST: a wrong secret is denied without leaking whether the key is expired/disabled.
143	    async fn resolve_cached(&self, key_id: ApiKeyId, secret: &[u8], cached: CachedValidation) -> Result<AuthnPrincipal, AuthnError> {
144	        if !self.hasher.verify(secret, &cached.key_hash) {
145	            return Err(invalid_token(ApiKeyDefect::BadSecret));
146	        }
147	        if cached.expires_at.is_some_and(|expires_at| expires_at <= self.clock.now()) {
148	            self.cache.evict(key_id).await;
149	            return Err(invalid_token(ApiKeyDefect::Expired));
150	        }
151	        if cached.sa_status != PrincipalStatus::Active {
152	            return Err(AuthnError::PrincipalInactive);
153	        }
154	
155	        Ok(AuthnPrincipal {
156	            principal_id: cached.principal_id,
157	            kind: PrincipalKind::ServiceAccount,
158	            status: PrincipalStatus::Active,
159	            credential: Credential::ApiKey {
160	                key_id,
161	                expires_at: cached.expires_at,
162	            },
163	        })
164	    }
165	
166	    /// The cache-MISS path: the full DB validation. Order of checks:
167	    ///
168	    /// 1. `keys.find_by_id(key_id)` — an unrecognized `key_id` -> `InvalidToken`.
169	    /// 2. `hasher.verify(secret, stored_hash)` (constant-time) — a mismatch -> `InvalidToken`.
170	    /// 3. The KEY's own `status == Active` and (`expires_at` is null OR in the future) — else
171	    ///    `InvalidToken`, best-effort `cache.evict` (belt-and-braces: this path is already a
172	    ///    cache miss, but a concurrent `put` could have just raced one in).
173	    /// 4. UNCONDITIONAL: the SA's live `Principal` (`principals.find_principal`) must exist, be
174	    ///    `PrincipalKind::ServiceAccount`, and be `PrincipalStatus::Active` — the module docs'
175	    ///    D16 guard. A missing principal or a kind mismatch is a backend data-integrity fault
176	    ///    (`AuthnError::Backend`, mirroring `authenticate_token.rs`'s own "principal missing"
177	    ///    guard); `Disabled` is the ordinary, expected outcome (`AuthnError::PrincipalInactive`).
178	    ///
179	    /// Only once every check passes does this `cache.put` the validation and best-effort
180	    /// `touch_last_used` (errors swallowed — never fails the request, module docs).
181	    async fn resolve_uncached(&self, parsed: ParsedToken) -> Result<AuthnPrincipal, AuthnError> {
182	        let key_id = parsed.key_id;
183	
184	        let (api_key, stored_hash) = self.keys.find_by_id(key_id).await.map_err(backend)?.ok_or_else(|| invalid_token(ApiKeyDefect::Malformed))?;
185	
186	        if !self.hasher.verify(&parsed.secret, &stored_hash) {
187	            return Err(invalid_token(ApiKeyDefect::BadSecret));
188	        }
189	
190	        let now = self.clock.now();
191	        if api_key.status != ApiKeyStatus::Active {
192	            self.cache.evict(key_id).await;
193	            return Err(invalid_token(ApiKeyDefect::Revoked));
194	        }
195	        if api_key.expires_at.is_some_and(|expires_at| expires_at <= now) {
196	            self.cache.evict(key_id).await;
197	            return Err(invalid_token(ApiKeyDefect::Expired));
198	        }
199	
200	        // D16, THE security-critical check (module docs): every miss-path resolve re-reads the
201	        // SA's live Principal status — a still-Active key belonging to a Disabled SA must never
202	        // authenticate.
203	        let sa_principal = self.principals.find_principal(&api_key.service_account_id).await.map_err(backend)?.ok_or_else(|| {
204	            AuthnError::Backend(Box::<dyn std::error::Error + Send + Sync>::from(
205	                "service account principal missing for an api key's service_account_id",
206	            ))
207	        })?;
208	
209	        if sa_principal.kind != PrincipalKind::ServiceAccount {
210	            return Err(AuthnError::Backend(Box::<dyn std::error::Error + Send + Sync>::from(
211	                "api key's service_account_id does not reference a service-account principal",
212	            )));
213	        }
214	        if sa_principal.status != PrincipalStatus::Active {
215	            return Err(AuthnError::PrincipalInactive);
216	        }
217	
218	        // Cache the stored hash alongside so the hit path can re-verify the secret without a DB
219	        // read (`stored_hash` is unused after this — move it in).
220	        self.cache
221	            .put(
222	                key_id,
223	                &CachedValidation {
224	                    principal_id: sa_principal.id.clone(),
225	                    sa_status: sa_principal.status,
226	                    expires_at: api_key.expires_at,
227	                    key_hash: stored_hash,
228	                },
229	            )
230	            .await;
231	
232	        // Best-effort: off the critical path, errors are swallowed (never fail the request on a
233	        // touch error).
234	        let _ = self.keys.touch_last_used(key_id, now, self.config.last_used_throttle_secs).await;
235	
236	        Ok(AuthnPrincipal {
237	            principal_id: sa_principal.id,
238	            kind: PrincipalKind::ServiceAccount,
239	            status: PrincipalStatus::Active,
240	            credential: Credential::ApiKey {
241	                key_id,
242	                expires_at: api_key.expires_at,
243	            },
244	        })
245	    }
246	
247	    /// Full authorization context for an API-key-authenticated request: `resolve` plus every
248	    /// membership row, paged internally — mirrors `AuthenticateToken::introspect`'s shape
249	    /// exactly (`authenticate_token.rs:144-166`), including `role_grants` staying empty (no
250	    /// current caller populates it from the `RoleGrantStore` here either).
251	    pub async fn introspect(&self, token: &str) -> Result<PrincipalContext, AuthnError> {
252	        let principal = self.resolve(token).await?;
253	
254	        let mut memberships = Vec::new();
255	        let mut offset = 0u64;
256	        loop {
257	            let page = self.memberships.list_by_principal(principal.principal_id.uuid(), MEMBERSHIP_PAGE_SIZE, offset).await.map_err(backend)?;
258	            let page_len = page.len() as u64;
259	            memberships.extend(page);
260	            if page_len < MEMBERSHIP_PAGE_SIZE {
261	                break;
262	            }
263	            offset += MEMBERSHIP_PAGE_SIZE;
264	        }
265	
266	        Ok(PrincipalContext {
267	            principal,
268	            memberships,
269	            role_grants: Vec::new(),
270	        })
271	    }
272	}
