429	    /// Seeds a fully valid, Active key (secret `[7u8; 32]`, `FakeSecretHasher`'s identity hash)
430	    /// for an Active `ServiceAccount` principal, plus the plaintext token that resolves it.
431	    /// Returns `(plaintext, key_id, sa_principal_id)`.
432	    fn seed_active_key(keys: &InMemoryApiKeys, principals: &InMemoryPrincipals, n: u128, expires_at: Option<chrono::DateTime<Utc>>) -> (String, ApiKeyId, PrincipalId) {
433	        let sa_id = principal_id(n);
434	        principals.seed(Principal::new(sa_id.clone(), PrincipalKind::ServiceAccount, PrincipalStatus::Active, epoch(), epoch()));
435	
436	        let id = key_id(n);
437	        let secret = [7u8; 32];
438	        let hash = FakeSecretHasher.hash(&secret);
439	        let key = ApiKey {
440	            id,
441	            service_account_id: sa_id.clone(),
442	            scope: scope(),
443	            prefix: display_prefix("pgs_sk_", id),
444	            status: ApiKeyStatus::Active,
445	            expires_at,
446	            last_used_at: None,
447	            created_at: epoch(),
448	            revoked_at: None,
449	            scope_actions: Vec::new(),
450	            scope_roles: Vec::new(),
451	        };
452	        keys.0.lock().unwrap().insert(id, (key, hash));
453	        let plaintext = format_token("pgs_sk_", id, &secret);
454	        (plaintext, id, sa_id)
455	    }
