54	/// Enough of a validated API key to rebuild an `AuthnPrincipal`, re-check expiry, AND
55	/// re-verify the presented secret on a cache hit (spec §9). Carries the resolved principal id,
56	/// the service account's current status, the key's own expiry, and `key_hash` — the SAME
57	/// peppered HMAC-SHA-256 tag stored in Postgres (`ApiKeyRepository::find_by_id`'s second
58	/// return), NOT the plaintext secret and NOT a new secret. Caching the stored hash is what lets
59	/// `AuthenticateApiKey`'s hit path skip the two DB round-trips (`find_by_id` + `find_principal`)
60	/// while STILL constant-time-verifying the presented secret against it on EVERY hit — a hit
61	/// keyed by `key_id` alone (a non-secret token segment) must never authenticate on the `key_id`
62	/// without also proving possession of the secret. A Redis leak of the hash can't validate keys
63	/// without the operator's pepper (which never leaves the process), so the hash is safe to cache.
64	#[derive(Debug, Clone, PartialEq, Eq)]
65	pub struct CachedValidation {
66	    pub principal_id: PrincipalId,
67	    pub sa_status: PrincipalStatus,
68	    pub expires_at: Option<DateTime<Utc>>,
69	    pub key_hash: Vec<u8>,
70	}
