72	/// The Redis wire payload for [`CachedValidation`]. `PrincipalId`/`PrincipalStatus` are pure
73	/// domain value types with no `serde` impls (core-crate purity, ADR-0005), so they're carried
74	/// as their string forms (`PrincipalId::canonical()` / `PrincipalStatus::as_str()`) and
75	/// reconstructed on read; `expires_at` is `chrono::DateTime<Utc>`, which already round-trips
76	/// via the workspace's `chrono/serde` feature (see `adapters::oidc::jwks::CachedJwks`); the raw
77	/// `key_hash` bytes are carried as standard base64 (`chrono/serde` won't serialize a bare
78	/// `Vec<u8>` compactly, and base64 mirrors how `pg_api_keys.rs` already stores the hash as text).
79	#[derive(Serialize, Deserialize)]
80	struct WireValidation {
81	    principal_prn: String,
82	    sa_status: String,
83	    expires_at: Option<DateTime<Utc>>,
84	    key_hash: String,
85	}
