87	impl From<&CachedValidation> for WireValidation {
88	    fn from(v: &CachedValidation) -> Self {
89	        WireValidation {
90	            principal_prn: v.principal_id.canonical(),
91	            sa_status: v.sa_status.as_str().to_string(),
92	            expires_at: v.expires_at,
93	            key_hash: STANDARD.encode(&v.key_hash),
94	        }
95	    }
96	}
