102	        let prn = Prn::parse(&w.principal_prn).map_err(|_| ())?;
103	        let sa_status = PrincipalStatus::parse(&w.sa_status).ok_or(())?;
104	        let key_hash = STANDARD.decode(&w.key_hash).map_err(|_| ())?;
105	        Ok(CachedValidation {
106	            principal_id: PrincipalId::from_prn(prn),
107	            sa_status,
108	            expires_at: w.expires_at,
