114	/// Per-`keyid` positive-validation cache (spec §9/D5). `get`/`put` are infallible by design
115	/// (fail-open, see module docs) so `AuthenticateApiKey.resolve` never has to special-case a
116	/// cache backend failure.
117	#[async_trait]
118	pub trait ApiKeyValidationCache: Send + Sync {
119	    /// Looks up `key_id`. Fail-open: any backend error (Redis unreachable, payload that fails
120	    /// to deserialize) degrades to `None`, indistinguishable from "never cached" — the caller
121	    /// always falls through to a real DB validation on a miss.
122	    async fn get(&self, key_id: ApiKeyId) -> Option<CachedValidation>;
123	
124	    /// Caches `v` for `key_id`. Fail-open: any backend error is logged and swallowed — a
125	    /// failed `put` never fails the validation that produced `v`.
126	    async fn put(&self, key_id: ApiKeyId, v: &CachedValidation);
127	
128	    /// Evicts `key_id`, e.g. on `RevokeApiKey`/`ArchiveServiceAccount`. Fail-open: any backend
129	    /// error is logged and swallowed.
130	    async fn evict(&self, key_id: ApiKeyId);
131	}
132	
133	/// In-process `ApiKeyValidationCache`: a TTL-bounded `Mutex<HashMap<..>>` — single-replica,
134	/// dev/single-node posture only (spec §9 challenge M5: `RevokeApiKey`/`ArchiveServiceAccount`
135	/// evictions here are local-replica only; HA deployments must use [`RedisApiKeyCache`] so
136	/// eviction is global).
137	pub struct MemoryApiKeyCache {
138	    ttl: Duration,
139	    entries: Mutex<HashMap<ApiKeyId, (CachedValidation, Instant)>>,
140	}
141	
142	impl MemoryApiKeyCache {
143	    /// `ttl_secs` bounds how long a `put` entry stays servable before `get` treats it as a
144	    /// miss and drops it — the same freshness bound `RedisApiKeyCache` gets from Redis's own
145	    /// `EX` expiry.
146	    #[must_use]
147	    pub fn new(ttl_secs: u64) -> Self {
148	        Self {
149	            ttl: Duration::from_secs(ttl_secs),
150	            entries: Mutex::new(HashMap::new()),
151	        }
152	    }
153	}
154	
155	#[async_trait]
156	impl ApiKeyValidationCache for MemoryApiKeyCache {
157	    async fn get(&self, key_id: ApiKeyId) -> Option<CachedValidation> {
158	        let mut entries = self.entries.lock().unwrap();
159	        match entries.get(&key_id) {
160	            Some((value, expires_at)) if *expires_at > Instant::now() => Some(value.clone()),
161	            Some(_) => {
162	                // Expired: drop it eagerly so a stale entry never leaks past its own TTL even
163	                // if nothing else evicts it first.
164	                entries.remove(&key_id);
165	                None
166	            }
167	            None => None,
168	        }
169	    }
170	
171	    async fn put(&self, key_id: ApiKeyId, v: &CachedValidation) {
172	        let expires_at = Instant::now() + self.ttl;
173	        self.entries.lock().unwrap().insert(key_id, (v.clone(), expires_at));
174	    }
175	
176	    async fn evict(&self, key_id: ApiKeyId) {
177	        self.entries.lock().unwrap().remove(&key_id);
178	    }
179	}
