181	/// `ApiKeyValidationCache` backed by Redis via an auto-reconnecting `ConnectionManager` (spec
182	/// §9), mirroring `adapters::authz::decision_cache::RedisDecisionCache`. Cheap to clone the
183	/// connection per call — `ConnectionManager` is itself `Arc`-backed and designed for
184	/// concurrent callers.
185	///
186	/// **Fail-open (D5):** every error path (connect, I/O, or (de)serialize) on `get` returns
187	/// `None` — a plain miss — and every error on `put`/`evict` is logged and swallowed. The
188	/// caller always falls through to a real DB validation on a miss, so a Redis outage only ever
189	/// costs the accelerator, never a validation.
190	pub struct RedisApiKeyCache {
191	    conn: ConnectionManager,
192	    ttl_secs: u64,
193	}
194	
195	impl RedisApiKeyCache {
196	    /// Opens `redis_url` and wraps it in a `ConnectionManager`. `ttl_secs` is applied to every
197	    /// `put` as Redis's own `EX` expiry — this cache is a fail-open accelerator, so an entry
198	    /// disappearing after `ttl_secs` (or on eviction) never surfaces as anything other than a
199	    /// subsequent miss.
200	    pub async fn connect(redis_url: &str, ttl_secs: u64) -> Result<Self, redis::RedisError> {
201	        let client = Client::open(redis_url)?;
202	        let conn = ConnectionManager::new(client).await?;
203	        Ok(Self { conn, ttl_secs })
204	    }
205	
206	    /// Builds a cache over an ALREADY-CONNECTED `ConnectionManager`: mirrors
207	    /// `RedisDecisionCache::from_connection`/`SliceCache::from_connection` (SMA-444 Task 21) —
208	    /// a future `AppState` wiring can share ONE redis connection across the redis-backed
209	    /// `Generations` + `RedisDecisionCache` + `SliceCache` + this cache rather than each
210	    /// opening its own; `connect` above stays the standalone-caller/test entry point.
211	    #[must_use]
212	    pub fn from_connection(conn: ConnectionManager, ttl_secs: u64) -> Self {
213	        Self { conn, ttl_secs }
214	    }
215	}
216	
217	#[async_trait]
218	impl ApiKeyValidationCache for RedisApiKeyCache {
219	    async fn get(&self, key_id: ApiKeyId) -> Option<CachedValidation> {
220	        let key = cache_key(key_id);
221	        let mut conn = self.conn.clone();
222	        let raw: Result<Option<Vec<u8>>, redis::RedisError> = conn.get(&key).await;
223	        match raw {
224	            Ok(Some(bytes)) => match serde_json::from_slice::<WireValidation>(&bytes).ok().and_then(|w| CachedValidation::try_from(w).ok()) {
225	                Some(v) => Some(v),
226	                None => {
227	                    log_deserialize_miss();
228	                    None
229	                }
230	            },
231	            Ok(None) => None,
232	            Err(err) => {
233	                log_get_miss(err.kind());
234	                None
235	            }
236	        }
237	    }
238	
239	    async fn put(&self, key_id: ApiKeyId, v: &CachedValidation) {
240	        let payload = match serde_json::to_vec(&WireValidation::from(v)) {
241	            Ok(payload) => payload,
242	            Err(_) => {
243	                log_serialize_swallow();
244	                return;
245	            }
246	        };
247	        let key = cache_key(key_id);
248	        let mut conn = self.conn.clone();
249	        let result: Result<(), redis::RedisError> = conn.set_ex(&key, payload, self.ttl_secs).await;
250	        if let Err(err) = result {
251	            log_put_swallow(err.kind());
252	        }
253	    }
254	
255	    async fn evict(&self, key_id: ApiKeyId) {
256	        let key = cache_key(key_id);
257	        let mut conn = self.conn.clone();
258	        let result: Result<(), redis::RedisError> = conn.del(&key).await;
259	        if let Err(err) = result {
260	            log_evict_swallow(err.kind());
261	        }
262	    }
263	}
264	
265	/// Logs the Redis error's `ErrorKind` only — never `Display`/message, which can echo
266	/// connection details (same posture as `oidc::redis_cache::log_unavailable` /
267	/// `decision_cache::log_get_miss`) — then the fail-open mapping: a get error degrades to a
268	/// plain miss (D5).
269	fn log_get_miss(kind: redis::ErrorKind) {
270	    tracing::warn!(error_kind = ?kind, "redis api key cache get error — treating as a miss (fail-open, D5)");
271	}
272	
273	fn log_deserialize_miss() {
274	    tracing::warn!(error_kind = "serde_json", "redis api key cache deserialize error — treating as a miss (fail-open, D5)");
275	}
276	
277	fn log_put_swallow(kind: redis::ErrorKind) {
278	    tracing::warn!(error_kind = ?kind, "redis api key cache put error — swallowed (fail-open, D5)");
279	}
280	
281	fn log_serialize_swallow() {
282	    tracing::warn!(error_kind = "serde_json", "redis api key cache serialize error — swallowed (fail-open, D5)");
283	}
284	
285	fn log_evict_swallow(kind: redis::ErrorKind) {
286	    tracing::warn!(error_kind = ?kind, "redis api key cache evict error — swallowed (fail-open, D5)");
287	}
