24	/// Extracts the bearer token from the `Authorization` header — the sole accepted
25	/// credential source on both surfaces (no cookies, no query parameters). Returns `None`
26	/// for an absent header, a non-UTF-8 value, a fused or non-`Bearer` scheme, or an empty
27	/// credential. The scheme match is ASCII-case-insensitive per RFC 7235 §2.1.
28	pub fn bearer_from_headers(headers: &HeaderMap) -> Option<String> {
29	    let value = headers.get(header::AUTHORIZATION)?.to_str().ok()?;
30	    let (scheme, token) = value.split_once(' ')?;
31	    if !scheme.eq_ignore_ascii_case("Bearer") {
32	        return None;
33	    }
34	    let token = token.trim();
35	    if token.is_empty() {
36	        return None;
37	    }
38	    Some(token.to_string())
39	}
