65	    /// every transport so they can never diverge: `actor` may always ask about themselves
66	    /// (`req.principal == actor`) and gets back the raw `Decision`. Asking about a DIFFERENT
67	    /// principal requires `actor` to already hold `Action::ListRoleGrants` AT `req.resource`
68	    /// — i.e. to already administer roles there. If that check denies,
69	    /// `TenancyError::Forbidden` propagates BEFORE `req` is ever decided for the probed
70	    /// principal — a caller who wasn't permitted to ask the question never sees a `Decision`
71	    /// (whose `determining_policies` can carry `grant:<uuid>` ids) or even the `allowed` bit.
72	    /// `adapters::http::authz::is_authorized` and `adapters::grpc::authz::AuthzGrpc::
73	    /// is_authorized` both call ONLY this (never `decide` directly) to decide a wire
74	    /// `IsAuthorized` request.
75	    pub async fn decide_gated(&self, actor: &Prn, req: &AccessRequest) -> Result<Decision, TenancyError> {
76	        if req.principal.canonical() != actor.canonical() {
77	            self.check(actor, Action::ListRoleGrants, &req.resource).await?;
78	        }
79	        Ok(self.decide(req).await?)
80	    }
81	}
