3	//! Service configuration via figment: built-in defaults < `gateway.toml` < `GATEWAY_*` env.
4	
5	use figment::providers::{Env, Format, Serialized, Toml};
6	use figment::{Figment, error::Error as FigmentError};
7	use secrecy::{ExposeSecret, SecretString};
8	use serde::{Deserialize, Serialize};
