11	/// M0 walking-skeleton config (see the module doc): one HTTP port, an IAM gRPC client
12	/// endpoint (G4 dials it), and the single OpenAI upstream (G6 calls out to it). No database,
13	/// no gRPC server of its own — mirrors `paigasus-iam::config::IamConfig`'s figment pattern
14	/// but is deliberately much smaller. Does NOT derive `PartialEq`: `upstream` transitively
15	/// carries `OpenAiConfig::api_key: SecretString`, which `secrecy` does not implement
16	/// `PartialEq` for (see `OpenAiConfig`'s doc).
17	#[derive(Debug, Clone, Deserialize, Serialize)]
18	pub struct GatewayConfig {
19	    pub http_addr: SocketAddr,
20	    pub connect_timeout_secs: u64,
21	    pub first_byte_timeout_secs: u64,
22	    pub stream_idle_timeout_secs: u64,
23	    pub max_request_bytes: usize,
24	    pub iam: IamClientConfig,
25	    pub upstream: UpstreamConfig,
26	    pub log_level: String,
27	}
28	
29	/// The IAM gRPC client endpoint G4 dials (`Introspect`/authorization calls). `tls` governs
30	/// how that channel is secured — see [`IamTlsConfig`]'s doc for the D8 rationale.
31	#[derive(Debug, Clone, Deserialize, Serialize, PartialEq, Eq)]
32	pub struct IamClientConfig {
33	    pub grpc_addr: String,
34	    pub tls: IamTlsConfig,
35	}
36	
37	/// D8: TLS is the default transport to `paigasus-iam`'s gRPC endpoint — the introspect call
38	/// carries raw caller-presented API keys, so the link must be encrypted unless an operator
39	/// EXPLICITLY opts into `loopback_insecure`, and even then only when `iam.grpc_addr` resolves
40	/// to a loopback host (checked in [`GatewayConfig::validate`] — `Deserialize` alone can't see
41	/// the sibling `grpc_addr` field to validate against). An enum (rather than a `bool` `enabled`
42	/// flag + always-present cert-path options) makes "insecure but cert paths configured" or
43	/// "secure but disabled" unrepresentable at the type level; G4 matches on this to build the
44	/// tonic channel.
45	#[derive(Debug, Clone, Deserialize, Serialize, PartialEq, Eq)]
46	#[serde(tag = "mode", rename_all = "snake_case")]
47	pub enum IamTlsConfig {
48	    Tls {
49	        /// Custom CA bundle to trust, in addition to (G4 decides: instead of, or alongside)
50	        /// the system trust store. `None` = system trust store only.
51	        #[serde(default)]
52	        ca_cert_path: Option<String>,
53	        /// mTLS client certificate. Must be set together with `client_key_path` or not at
54	        /// all — G4 validates that pairing when it builds the tonic channel.
55	        #[serde(default)]
56	        client_cert_path: Option<String>,
57	        #[serde(default)]
58	        client_key_path: Option<String>,
59	    },
60	    LoopbackInsecure,
61	}
62	
63	impl Default for IamClientConfig {
64	    fn default() -> Self {
65	        IamClientConfig {
66	            grpc_addr: "https://127.0.0.1:9090".to_string(),
67	            tls: IamTlsConfig::default(),
68	        }
69	    }
70	}
71	
72	impl Default for IamTlsConfig {
73	    fn default() -> Self {
74	        IamTlsConfig::Tls {
75	            ca_cert_path: None,
76	            client_cert_path: None,
77	            client_key_path: None,
78	        }
79	    }
80	}
