159	/// True when `grpc_addr`'s host is a loopback address (`127.0.0.0/8`, `localhost`, `::1`).
160	/// Deliberately a small hand-rolled parser rather than pulling in a `url` crate dependency
161	/// for a single boot-time check: `grpc_addr` is `scheme://host[:port]`, optionally with a
162	/// trailing path; strip the scheme, strip any path, then split the host from an optional
163	/// port (bracketed for IPv6 literals).
164	fn is_loopback_host(grpc_addr: &str) -> bool {
165	    let after_scheme = grpc_addr.split("://").last().unwrap_or(grpc_addr);
166	    let host_port = after_scheme.split('/').next().unwrap_or(after_scheme);
167	    let host = if let Some(rest) = host_port.strip_prefix('[') {
168	        // IPv6 literal, e.g. "[::1]:9090" or "[::1]".
169	        rest.split(']').next().unwrap_or(rest)
170	    } else {
171	        host_port.rsplit_once(':').map_or(host_port, |(h, _)| h)
172	    };
173	    host == "localhost" || host == "::1" || host.starts_with("127.")
174	}
