176	impl GatewayConfig {
177	    // `.split("__")` maps a DOUBLE-underscore in a `GATEWAY_*` env var to struct nesting, so
178	    // the OpenAI key can be injected without a config file: `GATEWAY_UPSTREAM__OPENAI__API_KEY`
179	    // -> `upstream.openai.api_key` (mirrors `paigasus-iam::config::IamConfig::figment`'s exact
180	    // rationale/split choice).
181	    #[must_use]
182	    pub fn figment() -> Figment {
183	        Figment::from(Serialized::defaults(Defaults::default()))
184	            .merge(Toml::file("gateway.toml"))
185	            .merge(Env::prefixed("GATEWAY_").split("__"))
186	    }
187	
188	    // `figment::Error` is a large enum (~208B); allow the size lint narrowly rather than
189	    // reshape the public signature the brief specifies (`main` calls this directly).
190	    #[allow(clippy::result_large_err)]
191	    pub fn load() -> Result<Self, FigmentError> {
192	        Self::figment().extract()
193	    }
194	
195	    /// Boot-time validation beyond what serde/figment structurally enforce: every
196	    /// `*_timeout_secs` is non-zero, `max_request_bytes` is non-zero, the OpenAI API key is
197	    /// non-empty (an empty key is a misconfiguration — reject at boot rather than fail every
198	    /// request at runtime), and — D8 — an `iam.tls = loopback_insecure` opt-out is only valid
199	    /// when `iam.grpc_addr` is a loopback host (the introspect link otherwise carries raw
200	    /// caller-presented API keys in the clear).
201	    pub fn validate(&self) -> Result<(), String> {
202	        for (name, secs) in [
203	            ("connect_timeout_secs", self.connect_timeout_secs),
204	            ("first_byte_timeout_secs", self.first_byte_timeout_secs),
205	            ("stream_idle_timeout_secs", self.stream_idle_timeout_secs),
206	        ] {
207	            if secs == 0 {
208	                return Err(format!("{name} must be at least 1 (0 disables the corresponding timeout)"));
209	            }
210	        }
211	
212	        if self.max_request_bytes == 0 {
213	            return Err("max_request_bytes must be at least 1".to_string());
214	        }
215	
216	        if self.upstream.openai.api_key.expose_secret().is_empty() {
217	            return Err("upstream.openai.api_key must not be empty (an empty key is a misconfiguration)".to_string());
218	        }
219	
220	        if matches!(self.iam.tls, IamTlsConfig::LoopbackInsecure) && !is_loopback_host(&self.iam.grpc_addr) {
221	            return Err(format!(
222	                "iam.tls = \"loopback_insecure\" requires iam.grpc_addr to be a loopback host (127.0.0.0/8, localhost, or ::1) — the introspect link otherwise carries raw API keys in the clear (D8); got {:?}",
223	                self.iam.grpc_addr
224	            ));
225	        }
226	
227	        Ok(())
228	    }
229	}
