23	/// What a request the mock received looked like (captured before any response is produced).
24	#[derive(Clone)]
25	pub struct RecordedRequest {
26	    /// The exact headers reqwest sent upstream — asserted against for header hygiene.
27	    pub headers: HeaderMap,
28	    /// The raw request body bytes (proves byte-lossless passthrough).
29	    pub body: Bytes,
30	}
31	
32	impl RecordedRequest {
33	    /// The value of a request header as a `&str`, or `None` if absent / non-ASCII.
34	    pub fn header(&self, name: &str) -> Option<&str> {
35	        self.headers.get(name).and_then(|v| v.to_str().ok())
36	    }
37	}
38	
39	/// How the mock should answer `POST /v1/chat/completions`.
40	#[derive(Clone)]
41	enum MockResponse {
42	    /// Non-stream: return `status` with the given JSON body.
43	    Json { status: StatusCode, body: String },
44	    /// Stream: return `200 text/event-stream`, emitting each element as a `data: <event>\n\n`
45	    /// frame IN ORDER, streamed (never buffered into one blob server-side).
46	    Sse { events: Vec<String> },
47	}
48	
49	struct MockState {
50	    response: MockResponse,
51	    recorded: Mutex<Option<RecordedRequest>>,
52	}
53	
54	/// A running mock OpenAI server. Its `base_url` is what you feed into [`OpenAiConfig`]; the server
55	/// task is aborted on drop.
56	pub struct MockOpenAi {
57	    /// `http://127.0.0.1:<port>` — pass straight to `OpenAiConfig::base_url`.
58	    pub base_url: String,
59	    state: Arc<MockState>,
60	    handle: tokio::task::JoinHandle<()>,
61	}
62	
63	impl Drop for MockOpenAi {
64	    fn drop(&mut self) {
65	        self.handle.abort();
66	    }
67	}
68	
69	impl MockOpenAi {
70	    /// Start a mock that returns a canned JSON body with the given status (the non-stream path).
71	    pub async fn spawn_json(status: StatusCode, body: impl Into<String>) -> Self {
72	        Self::spawn(MockResponse::Json { status, body: body.into() }).await
73	    }
74	
75	    /// Start a mock that streams the given events IN ORDER as SSE `data:` frames (the stream path).
76	    pub async fn spawn_sse(events: Vec<String>) -> Self {
77	        Self::spawn(MockResponse::Sse { events }).await
78	    }
79	
80	    async fn spawn(response: MockResponse) -> Self {
81	        let state = Arc::new(MockState { response, recorded: Mutex::new(None) });
82	        let router = Router::new().route("/v1/chat/completions", post(handle)).with_state(state.clone());
83	
84	        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.expect("bind ephemeral port");
85	        let addr = listener.local_addr().expect("local addr");
86	        let base_url = format!("http://{addr}");
87	
88	        let handle = tokio::spawn(async move {
89	            axum::serve(listener, router).await.expect("mock openai server");
90	        });
91	
92	        MockOpenAi { base_url, state, handle }
93	    }
94	
95	    /// The request the mock last recorded (headers + body), or `None` if none arrived yet.
96	    pub fn recorded(&self) -> Option<RecordedRequest> {
97	        self.state.recorded.lock().expect("recorded lock not poisoned").clone()
98	    }
99	}
