101	/// Records the inbound request, then answers per the configured [`MockResponse`]. `Bytes` is the
102	/// body-consuming extractor, so it comes last.
103	async fn handle(State(state): State<Arc<MockState>>, headers: HeaderMap, body: Bytes) -> Response {
104	    *state.recorded.lock().expect("recorded lock not poisoned") = Some(RecordedRequest {
105	        headers: headers.clone(),
106	        body: body.clone(),
107	    });
108	
109	    match &state.response {
110	        MockResponse::Json { status, body } => (*status, [(axum::http::header::CONTENT_TYPE, "application/json")], body.clone()).into_response(),
111	        MockResponse::Sse { events } => {
112	            // Stream each event as its own frame via `Body::from_stream` — genuinely streamed
113	            // (frame by frame) rather than concatenated into a single buffered body, so the client
114	            // side exercises real incremental delivery.
115	            let frames = events.clone();
116	            let stream = futures::stream::iter(frames.into_iter().map(|e| Ok::<Bytes, std::convert::Infallible>(Bytes::from(format!("data: {e}\n\n")))));
117	            Response::builder()
118	                .status(StatusCode::OK)
119	                .header(axum::http::header::CONTENT_TYPE, "text/event-stream")
120	                .body(Body::from_stream(stream))
121	                .expect("build sse response")
122	        }
123	    }
124	}
